"""Regenerate internal/sidecar/embedded.mbt from built sidecar executables.

Usage: python3 scripts/embed_sidecar.py KEY=PATH [KEY=PATH ...]

KEY is "<os>-<arch>" as produced by `internal/sidecar` (for example
`macos-arm64`, `linux-x86_64`). Run with no arguments to reset the table."""
import sys

entries = []
for arg in sys.argv[1:]:
    key, path = arg.split("=", 1)
    entries.append((key, open(path, "rb").read()))

out = ["///|",
       "/// Sidecar executables keyed by `<os>-<arch>`. Generated by",
       "/// `scripts/embed_sidecar.py`; do not edit by hand.",
       "let embedded_sidecars : Map[String, Bytes] = {"]
for key, data in entries:
    out.append('  "%s": (' % key)
    chunks = [data[i : i + 64] for i in range(0, len(data), 64)]
    for i, chunk in enumerate(chunks):
        sep = " +" if i + 1 < len(chunks) else ""
        out.append('    b"' + "".join("\\x%02x" % b for b in chunk) + '"' + sep)
    out.append("  ),")
out.append("}")
print("\n".join(out))
